```js
// Strict 8.44 helpers. Native records/skin metadata are the reference; no runtime trajectories.
import assert from 'node:assert/strict';
import { VertexList } from '../../ui/kit/prims.mjs';
import { findIn } from '../ui41/run41.mjs';

export function coverage844(index) {
  const entries = Object.entries(index.states);
  const stat = entries.filter(([, s]) => s.scenario.startsWith('a844-'));
  assert.equal(entries.length, 186, 'strict8.44: all states');
  assert.equal(stat.length, 14, 'strict8.44: static states');
  assert.equal(new Set(stat.map(([, s]) => s.png_sha256)).size, 14);
  for (const [id, s] of entries) {
    assert.equal(s.repeat_equal, true, id + ': A/B');
    assert.equal(s.menu_drawn, true, id + ': controller missing');
  }
  for (const [scenario, prefix, last] of [['e844-cc', 'c', 830], ['e844-ce', 'e', 860]]) {
    const rows = entries.filter(([, s]) => s.scenario === scenario);
    assert.deepEqual(rows.map(([, s]) => s.frame).sort((a, b) => a - b),
      Array.from({ length: last - 759 }, (_, i) => 760 + i), scenario + ': continuity');
    for (const [id, s] of rows)
      assert.equal(id, scenario + '--' + prefix + String(s.frame).padStart(4, '0'));
  }
  assert.equal(entries.filter(([, s]) => s.scenario.startsWith('e844-')).length, 172);
  return { static: 14, common: 71, epic: 101, animation: 172, all: 186 };
}

export function event844(st0, inputs) {
  const value = inputs.events?.[st0.scenario];
  if (!value) {
    assert.ok(st0.scenario.startsWith('a844-'), 'missing creation event: ' + st0.scenario);
    return null;
  }
  const e = structuredClone(value);
  assert.deepEqual(Object.keys(e).sort(),
    ['createdAtMs', 'x', 'y', 'idol', 'rarity', 'first', 'L', 'H', 'D', 'beta', 'S'].sort());
  return e;
}

export function apply844(state, st0, inputs) {
  const e = event844(st0, inputs);
  if (!e) return state;
  const nowMs = Math.floor(1000 * st0.frame / 60);
  if (nowMs < e.createdAtMs) return { ...state, nowMs, effects: [] };
  const owned = [...state.owned], fragments = [...state.fragments];
  const cost = [...state.cost], crafts = [...state.crafts];
  assert.equal(cost[e.rarity], 1, 'single creation fixture spends the old price');
  owned[e.idol] += 1;
  fragments[e.rarity] -= cost[e.rarity];
  crafts[e.rarity] += 1;
  cost[e.rarity] = 1.1 - 1 / 3250;
  return { ...state, owned, fragments, cost, crafts, nowMs, effects: [e] };
}

function mode844(mode) {
  if (mode === 0 || mode === 'normal') return 0;
  if (mode === 1 || mode === 'add' || mode === 'additive') return 1;
  throw new Error('strict8.44: unsupported blend ' + JSON.stringify(mode));
}

/** State setters have no vertices; every drawable remains and its effective blend is checked. */
export function paint844(leaves) {
  let mode = 0;
  const paint = [];
  leaves.forEach((input, sourceIndex) => {
    if (input.component === 'blend') {
      mode = mode844(input.mode);
      return;
    }
    const leaf = { ...input };
    const effective = leaf.blend === undefined ? mode : mode844(leaf.blend);
    delete leaf.blend;
    assert.ok(['sprite', 'text', 'rect', 'line'].includes(leaf.component),
      'strict8.44: unhandled drawable ' + JSON.stringify(leaf));
    paint.push({ leaf, mode: effective, sourceIndex });
  });
  return { paint, finalMode: mode };
}

export function sourceFx844(entries) {
  const { paint, finalMode } = paint844(entries.map((e) => e.leaf));
  assert.equal(finalMode, 0, 'native blend must be restored');
  const text = paint.map((p, i) =>
    entries[p.sourceIndex].fn === 'F_DrawTextTransformed' ? i : -1
  ).filter((i) => i >= 0);
  if (!text.length) return [];
  let first = text[0];
  const keys​ = new Set([
    'sprite.circle', 'sprite.star16x16', 'sprite.arch_idol_bgs', 'sprite.arch_idols',
  ]);
  while (first > 0 && paint[first - 1].leaf.component === 'sprite' &&
    keys.has(paint[first - 1].leaf.sprite)) first--;
  const fx = paint.slice(first, text.at(-1) + 1);
  assert.ok(fx[0].leaf.component === 'sprite');
  return fx;
}

const ORDER = [0, 1, 2, 2, 3, 0];
const F = Math.fround;

/** Native arguments + skin metadata only: no runtime layout or trajectory generates the reference. */
export function signature844(paint, skin, strings) {
  const signature = [], spans = [];
  for (const p of paint) {
    const leaf = p.leaf, quads = [], from = signature.length;
    if (leaf.component === 'sprite') {
      const sprite = skin.sprite(leaf.sprite);
      assert.equal(sprite.nine, null, 'FX sprite must be a whole quad');
      const frame = sprite.frames[leaf.frame ?? 0];
      quads.push({ src: frame.src, size: frame.atlasSize });
    } else {
      assert.equal(leaf.component, 'text');
      const font = skin.font(leaf.font);
      const text = leaf.text === undefined ? String(leaf.value) : strings[leaf.text];
      assert.equal(typeof text, 'string');
      for (const ch of text) {
        const g = font.glyphs.get(ch.codePointAt(0));
        assert.ok(g, 'native FX glyph missing: ' + ch);
        quads.push({
          src: [font.pageX + g.x - 1, font.pageY + g.y - 1, g.w + 2, g.h + 2],
          size: font.atlasSize,
        });
      }
    }
    for (const { src: [x, y, w, h], size: [W, H] } of quads) {
      const q = [
        [F(x / W), F(y / H)],
        [F((x + w) / W), F(y / H)],
        [F((x + w) / W), F((y + h) / H)],
        [F(x / W), F((y + h) / H)],
      ];
      for (const k of ORDER) signature.push(q[k]);
    }
    spans.push([from, signature.length]);
  }
  return { signature, spans };
}

export function locateFx844(stream, signature) {
  assert.ok(signature.length > 0);
  const hits = [];
  for (let j = 0; j + signature.length <= stream.n; j++) {
    let k = 0;
    while (k < signature.length &&
      stream.U[j + k] === signature[k][0] &&
      stream.V[j + k] === signature[k][1]) k++;
    if (k === signature.length) hits.push(j);
  }
  assert.equal(hits.length, 1,
    'native FX UV range must be unique: ' + JSON.stringify(hits));
  return hits[0];
}

export const blend844 = (mode) =>
  [1, 770, mode === 1 ? 1 : 771, 770, mode === 1 ? 1 : 771, 32774, 32774];

export function comparePaint844(ours, original, norm, strings) {
  for (let i = 0; i < Math.max(ours.length, original.length); i++) {
    const a = ours[i], b = original[i];
    if (!a || !b || a.mode !== b.mode ||
      norm(a.leaf, strings) !== norm(b.leaf, strings))
      return { at: i, ours: a, o: b };
  }
  return null;
}

/** Check bounded native geometry and actual GL blend against both source and runtime leaves. */
export function checkFx844({ stream, native, ours, skin, strings, build, norm }) {
  assert.equal(ours.finalMode, 0, 'runtime blend must be restored');
  const diff = comparePaint844(ours.paint, native, norm, strings);
  const out = {
    fx_leaves_o: native.length,
    fx_leaves_ours: ours.paint.length,
    fx_equal: !diff,
    fx_vertices_equal: false,
    fx_blend_equal: true,
    fx_depth_equal: true,
    fx_vertices: 0,
    fx_span: null,
  };
  if (diff) out.fx_leaf_diff = diff;
  if (!native.length) {
    out.fx_vertices_equal = ours.paint.length === 0;
    return out;
  }
  const { signature, spans } = signature844(native, skin, strings);
  const start = locateFx844(stream, signature), end = start + signature.length;
  out.fx_span = [start, end];
  out.fx_vertices = signature.length;
  const v = new VertexList();
  let counts = native.length === ours.paint.length, skipped = 0;
  for (let i = 0; i < ours.paint.length; i++) {
    const before = v.count;
    skipped += build(v, [ours.paint[i].leaf]);
    if (!spans[i] || v.count - before !== spans[i][1] - spans[i][0])
      counts = false;
  }
  out.fx_vertices_equal = counts && skipped === 0 &&
    v.count === signature.length && findIn(stream, v, start, end).j === start;
  for (let i = 0; i < native.length; i++) {
    for (let k = spans[i][0]; k < spans[i][1]; k++) {
      const draw = stream.draws.get(stream.D[start + k]);
      const actual = JSON.stringify(draw.blend);
      if (actual !== JSON.stringify(blend844(native[i].mode)) ||
        actual !== JSON.stringify(blend844(ours.paint[i]?.mode)))
        out.fx_blend_equal = false;
      if (stream.Z[start + k] !== -99) out.fx_depth_equal = false;
    }
  }
  return out;
}
